INSERT INTO movement (movement_key, name, description) VALUES
    ('barbell_squat', 'Barbell squat', 'A barbell squat is a squat with a barbell on the upper back. Lower until the thighs are below parallel, then stand back up.'),
    ('butterfly_stretch', 'Butterfly Stretch', 'Sit with the soles of the feet together and knees open to stretch the inner thighs.'),
    ('cat_cow', 'Cat-Cow', 'Alternate between rounding and gently arching the spine from hands and knees.'),
    ('chicken_pushup', 'Chicken pushup', 'A chicken pushup is a pushup with the knees on the floor. Lower the chest to the floor, then press back up.'),
    ('childs_pose', 'Child''s Pose', 'Rest the torso forward from kneeling, with the arms reaching ahead and the forehead supported.'),
    ('cobra_pose', 'Cobra Pose', 'Lift the chest into a small backbend while lying face down, keeping the pelvis and legs grounded.'),
    ('dead_bug', 'Dead Bug', 'Lower an opposite arm and leg while lying on the back, keeping the trunk steady.'),
    ('dead_hang', 'Dead Hang', 'Hang from a fixed overhead bar with straight arms to practice grip and overhead support.'),
    ('deadlift', 'Deadlift', 'A deadlift is lifting a barbell from the floor to standing. Bend at the hips and knees to grip the bar, then stand up with the bar.'),
    ('downward_facing_dog', 'Downward-Facing Dog', 'Form an inverted V on hands and feet, reaching the hips up and back while lengthening the spine.'),
    ('forearm_plank', 'Forearm Plank', 'Hold the body above the floor on the forearms and toes to train trunk stability.'),
    ('glute_bridge', 'Glute Bridge', 'Raise the hips from a bent-knee lying position to train hip extension.'),
    ('handstand_pushup', 'Handstand pushup', 'A handstand pushup is a pushup while doing a handstand. Hold a handstand, lower the head toward the floor between the hands, then press back up.'),
    ('hollow_body_hold', 'Hollow Body Hold', 'Hold a compact, rounded trunk position on the back, with shoulders and feet off the floor.'),
    ('inverted_row', 'Inverted Row', 'Pull the chest toward a fixed bar while the heels remain on the floor.'),
    ('jefferson_curl', 'Jefferson Curl (Unloaded)', 'Slowly roll the spine forward and return to standing without added weight, practicing controlled spinal flexion.'),
    ('low_lunge', 'Low Lunge', 'Hold a kneeling lunge to stretch the front of the rear hip while keeping the trunk upright.'),
    ('pancake_stretch', 'Pancake Stretch', 'Fold forward from a wide seated straddle to stretch the inner thighs and hamstrings.'),
    ('parallel_bar_dip', 'Parallel Bar Dip', 'Lower and raise the body between fixed parallel bars using the chest and arms.'),
    ('pike_pushup', 'Pike pushup', 'A pike pushup is a pushup with the hips high and the body in an inverted V. Lower the head toward the floor between the hands, then press back up.'),
    ('pistol_squats', 'Pistol squats', 'A pistol squat is a squat on one leg, with the other leg held straight in front. Lower as deep as possible, then stand back up.'),
    ('planche_lean', 'Planche lean', 'A planche lean is holding a straight-arm plank with the shoulders leaning forward past the hands.'),
    ('pseudo_planche_pushup', 'Pseudo planche pushup', 'A pseudo planche pushup is a pushup with the hands by the waist and the shoulders forward over the hands. Lower the chest to the floor, then press back up.'),
    ('pullup', 'Pullup', 'A pullup is pulling the body up on a bar with the arms. Hang from the bar, pull up until the chin is over the bar, then lower back down.'),
    ('push_up', 'Push up', 'A pushup is pressing the body away from the floor with the hands, while the body stays straight. Lower the chest to the floor, then press back up.'),
    ('reverse_lunge', 'Reverse Lunge', 'Step backward into a split stance, lower the body, then return to standing.'),
    ('scapular_pullup', 'Scapular Pullup', 'Raise the body a small distance from a hang using the shoulder blades while keeping the elbows straight.'),
    ('seated_forward_fold', 'Seated Forward Fold', 'Hinge forward over the legs from sitting to stretch the hamstrings while keeping the back long.'),
    ('side_plank', 'Side Plank', 'Support the body sideways on one forearm and the feet to train lateral trunk stability.'),
    ('squats', 'Squats', 'A squat is lowering the body by bending the knees and hips. Lower until the thighs are below parallel, then stand back up.'),
    ('supine_figure_four_stretch', 'Supine Figure-Four Stretch', 'Cross one ankle over the opposite thigh while lying on the back to stretch the outer hip.'),
    ('toes_to_bar', 'Toes to bar', 'Toes to bar is raising the legs while hanging from a bar. Hang from the bar, raise the legs until the toes touch the bar, then lower back down.'),
    ('wide_arm_pullup', 'Wide arm pullup', 'A wide arm pullup is a pullup with the hands wider than the shoulders. Hang from the bar, pull up until the chin is over the bar, then lower back down.');
INSERT INTO movement_item (movement_key, position, type, content) VALUES
    ('barbell_squat', 0, 'CUE', 'Barbell on the upper back, held with both hands'),
