INSERT INTO movement_stage (movement_key, position, name, description) VALUES
    ('barbell_squat', 0, 'Eccentric', 'Deepest squat with the barbell on the upper back, thighs below parallel, chest up, back flat.'),
    ('barbell_squat', 1, 'Concentric', 'Standing tall with the barbell on the upper back, hips and knees locked.'),
    ('butterfly_stretch', 0, 'Hold', 'Seated upright with soles of feet touching, knees open to the sides and hands lightly holding the ankles. Back long and shoulders relaxed.'),
    ('cat_cow', 0, 'Cat', 'On hands and knees with arms straight, back rounded toward the ceiling, pelvis tucked and chin gently lowered.'),
    ('cat_cow', 1, 'Cow', 'On hands and knees with arms straight, pelvis tilted forward, belly lowered slightly and chest lifted forward. Neck follows the curve of the spine without the head being thrown back.'),
    ('chicken_pushup', 0, 'Eccentric', 'Knees on the floor, chest to floor, elbows tucked, body straight from head to knees.'),
    ('chicken_pushup', 1, 'Concentric', 'Knees on the floor, elbows locked, body straight from head to knees.'),
    ('childs_pose', 0, 'Hold', 'Kneeling with knees apart, tops of feet on the floor and hips toward heels. Torso rests forward between thighs, arms reach along the floor and forehead is supported on the floor.'),
    ('cobra_pose', 0, 'Hold', 'Lying face down with pelvis, legs and tops of feet grounded. Chest lifted a short distance, palms beside lower ribs, elbows bent alongside the torso and neck long.'),
    ('dead_bug', 0, 'Start', 'Lying on the back with arms vertical, thighs vertical, knees bent to right angles and shins parallel to the floor.'),
    ('dead_bug', 1, 'Reach', 'Lying on the back with one arm extended overhead and the opposite leg extended above the floor. Other arm remains vertical and other hip and knee remain bent; lower back stays on the floor.'),
    ('dead_hang', 0, 'Hang', 'Hanging vertically from a fixed overhead bar with straight arms, overhand grip and feet off the floor. Head sits between the upper arms and legs hang together.'),
    ('deadlift', 0, 'Eccentric', 'Barbell on the floor, hips low, back flat, arms straight, hands outside the knees.'),
    ('deadlift', 1, 'Concentric', 'Standing tall, hips and knees locked, barbell held at the thighs, shoulders back.'),
    ('downward_facing_dog', 0, 'Hold', 'Hands and feet on the floor in an inverted V, hips high, arms straight and back long. Knees slightly bent, heels raised, and head aligned between the upper arms.'),
    ('forearm_plank', 0, 'Hold', 'Body supported on parallel forearms and toes, elbows beneath shoulders. Head, hips and heels form a straight line, with the face toward the floor.'),
    ('glute_bridge', 0, 'Start', 'Lying on the back with knees bent, feet flat and hip-width apart, and arms resting beside the body.'),
    ('glute_bridge', 1, 'Top', 'Shoulders and feet on the floor, hips raised into a straight line with shoulders and knees. Knees remain aligned with feet and arms rest beside the body.'),
    ('handstand_pushup', 0, 'Eccentric', 'Head to the floor between the hands, elbows bent, body inverted and straight.'),
    ('handstand_pushup', 1, 'Concentric', 'Elbows locked in a handstand, body inverted and straight.'),
    ('hollow_body_hold', 0, 'Hold', 'Lower back on the floor, shoulder blades lifted, arms reaching beside the thighs. Hips and knees bent with feet raised; chin gently tucked.'),
    ('inverted_row', 0, 'Bottom', 'Body beneath a fixed bar with arms straight and heels on the floor. Head, hips and heels align in a straight diagonal line.'),
    ('inverted_row', 1, 'Top', 'Chest close to the fixed bar, elbows bent beside the body and heels on the floor. Head, hips and heels remain aligned.'),
    ('jefferson_curl', 0, 'Standing', 'Standing upright on the floor, feet hip-width apart, knees softly bent, arms hanging by the sides and hands empty.'),
    ('jefferson_curl', 1, 'Rolled down', 'Standing with softly bent knees, hips shifted slightly backward and spine rounded forward. Head and empty hands hang toward the floor, without reaching below foot level.'),
    ('low_lunge', 0, 'Hold', 'Half-kneeling with front foot flat, front knee above ankle and rear knee on a folded mat behind the hip. Torso upright, pelvis facing forward and hands resting on the front thigh.'),
    ('pancake_stretch', 0, 'Hold', 'Seated with legs spread wide, knees and toes facing upward, and heels on the floor. Torso leans forward from the hips with a long back and hands resting on the floor ahead.'),
    ('parallel_bar_dip', 0, 'Support', 'Body supported above two fixed parallel bars with straight arms, hands beside hips, shoulders lowered and feet clear of the floor.'),
    ('parallel_bar_dip', 1, 'Lowered', 'Body lowered between parallel bars with elbows bent, upper arms approximately horizontal and forearms near vertical. Torso leans slightly forward, knees are bent and feet remain clear of the floor.'),
    ('pike_pushup', 0, 'Eccentric', 'Head near the floor between the hands, elbows bent, hips high in an inverted V, legs straight.'),
    ('pike_pushup', 1, 'Concentric', 'Elbows locked, hips high in an inverted V, legs straight.'),
    ('pistol_squats', 0, 'Eccentric', 'Deepest single-leg squat, the other leg straight out in front, chest up, arms forward.'),
    ('pistol_squats', 1, 'Concentric', 'Standing tall on one leg, the other leg straight out in front, arms forward.'),
    ('planche_lean', 0, 'Start', 'Straight-arm plank, shoulders over the hands, body straight.'),
    ('planche_lean', 1, 'Lean', 'Shoulders forward past the hands, arms straight, body straight.'),
    ('pseudo_planche_pushup', 0, 'Eccentric', 'Chest to floor, hands by the waist, shoulders forward over the hands, elbows tucked, body straight.'),
    ('pseudo_planche_pushup', 1, 'Concentric', 'Elbows locked, hands by the waist, shoulders forward over the hands, body straight. Scapulae protrected.'),
    ('pullup', 0, 'Eccentric', 'Dead hang from the bar, arms straight, body straight.'),
    ('pullup', 1, 'Concentric', 'Chin over the bar, elbows bent, body straight.'),
    ('push_up', 0, 'Eccentric', 'Chest to floor, elbows tucked, body straight.'),
    ('push_up', 1, 'Concentric', 'Elbows locked, body straight.'),
    ('reverse_lunge', 0, 'Standing', 'Standing upright with feet hip-width apart and arms by the sides.'),
    ('reverse_lunge', 1, 'Lowered', 'One foot forward and flat, other foot behind on the ball of the foot. Both knees bent, rear knee hovering above the floor, front thigh near horizontal, and torso nearly upright.'),
    ('scapular_pullup', 0, 'Hang', 'Body hanging vertically from an overhead bar, arms straight and shoulders raised near the ears. Legs hang together.'),
    ('scapular_pullup', 1, 'Active hang', 'Body slightly higher beneath the same bar, arms still straight and shoulders farther from the ears. Chest is slightly lifted without bending the elbows or arching the lower back.'),
    ('seated_forward_fold', 0, 'Hold', 'Seated with legs together in front, knees slightly bent and toes upward. Torso leans forward from the hips, spine long and hands resting on the shins.'),
    ('side_plank', 0, 'Hold', 'Body sideways above the floor, supported on one forearm and stacked feet. Elbow beneath shoulder, hips lifted, free hand on the upper hip, and head aligned with the torso.'),
    ('squats', 0, 'Eccentric', 'Deepest squat, thighs below parallel, knees over the toes, chest up, arms forward.'),
    ('squats', 1, 'Concentric', 'Standing tall, hips and knees locked, arms forward.'),
    ('supine_figure_four_stretch', 0, 'Hold', 'Lying on the back with one ankle crossed above the opposite knee. Both hands hold behind the supporting thigh, drawing it toward the chest; head and pelvis rest on the floor.'),
    ('toes_to_bar', 0, 'Eccentric', 'Dead hang from the bar, arms straight, legs straight and together.'),
    ('toes_to_bar', 1, 'Concentric', 'Toes touching the bar, legs straight and together, arms straight.'),
    ('wide_arm_pullup', 0, 'Eccentric', 'Dead hang from the bar with a wide grip, arms straight, body straight.'),
    ('wide_arm_pullup', 1, 'Concentric', 'Chin over the bar with a wide grip, elbows out to the sides, body straight.');
